/**
 * @file    app.h
 * @brief   Application layer of the STM32 Embedded Sensor Gateway.
 *
 * main.c (generated by STM32CubeMX) only needs two calls:
 *
 *     USER CODE BEGIN 2 :  app_init();
 *     USER CODE BEGIN 3 :  app_loop();   (inside while(1))
 */
#ifndef APP_APP_H
#define APP_APP_H

void app_init(void);
void app_loop(void);

#endif /* APP_APP_H */
